          listFeedUser: _listUserData,
          isFullLoaded: _isFullLoaded,
          isMaxSeen: false,
          page: _offSet));
    }
  }
}

Future<FilesMeta> calculateSimilarity({
  required List<FaceModel> faceModel,
  PickPhotoModel? pickPhotoModel,
  PickPhotoProfileModel? pickPhotoProfileModel,
  int? key,
}) async {
  List<FilesMeta> listFilesMeta = List.empty(growable: true);
  final Uint8List? templateSelfie =
      await CacheUtil.getUint8List(Strings.keyTemplateSelfie);

  if (templateSelfie == null) {
    return FilesMeta(
      filename: pickPhotoModel?.photo.name ?? pickPhotoProfileModel?.photo?.name,
      order: key,
      similarity: 0.1,
    );
  }

  for (var el in faceModel) {
    double similarity = (await _facesdkPlugin.similarityCalculation(
      el.templates!,
      templateSelfie,
    )) ?? 0.1;
    listFilesMeta.add(FilesMeta(
      filename: pickPhotoModel?.photo.name ?? pickPhotoProfileModel?.photo?.name,
      order: key,
      similarity: similarity,
      meta: MetaKBY.fromJson(el.toJson()),
    ));
  }

  final highestValue = listFilesMeta.reduce((value, element) =>
      (value.similarity ?? 0.1) > (element.similarity ?? 0.1) ? value : element);
  return highestValue;
}

class BillingService {
  late final InAppPurchase _inAppPurchase;
  late final Stream<List<PurchaseDetails>> _stream;

  BillingService() {
    _inAppPurchase = InAppPurchase.instance;
    _stream = _inAppPurchase.purchaseStream;
  }

  void initPayment({
    required Future<void> Function(PurchaseDetails) onVerifyPurchase,
    required Future<void> Function() onPendingCompletePurchase,
    required Future<void> Function(IAPError, PurchaseDetails) onStatusError,
  }) async {
    _stream.listen((purchaseDetailsList) async {
      for (var purchaseDetails in purchaseDetailsList) {
        if (purchaseDetails.status == PurchaseStatus.purchased) {
          await onVerifyPurchase(purchaseDetails);
        } else if (purchaseDetails.status == PurchaseStatus.error) {
          onStatusError(purchaseDetails.error!, purchaseDetails);
        }
        if (purchaseDetails.pendingCompletePurchase) {
          onPendingCompletePurchase();
          _inAppPurchase.completePurchase(purchaseDetails);
        }
      }
    });

    if (Platform.isIOS) {
      var iosAddition = _inAppPurchase
          .getPlatformAddition<InAppPurchaseStoreKitPlatformAddition>();
      await iosAddition.setDelegate(IosPaymentQueueDelegate());
    }
  }
}

class StringOrIntConverterNum implements JsonConverter<num?, dynamic> {
  const StringOrIntConverterNum();

  @override
  num? fromJson(dynamic json) {
    if (json is int) return json;
    if (json is String) return int.tryParse(json);
    return null;
  }

  @override
  toJson(num? object) => object;
}

class ArrayIntOrIntConverter implements JsonConverter<num?, dynamic> {
  const ArrayIntOrIntConverter();

  @override
  num? fromJson(dynamic json) {
    if (json is num) return json;
    if (json is List) {
      final list = (json).map<int>((e) => e).toList();
      if (list.isEmpty) return null;
      return list[0];
    }
    return null;
  }

  @override
  toJson(num? object) => object;
}
